/// Coordinator for pyflakes rewrites, format-string analysis, unused binding
/// cleanup, and related source repairs.
#[derive(Debug, Clone, Default)]
pub(crate) struct RewriteCoordinator {
    unused_positional_indexes: Vec<usize>,
    unused_keyword_indexes: Vec<usize>,
    unused_dict_indexes: Vec<usize>,
    auto_fields: Vec<usize>,
    index_fields: Vec<usize>,
    keyword_fields: Vec<Name>,
    nested_format_parts: bool,
    format_error: Option<String>,
    percent_starred: bool,
    percent_positional: usize,
    percent_keywords: FxHashSet<String>,
    percent_error: Option<String>,
    percent_unsupported_char: Option<char>,
    dummy_variable_pattern: String,
    preview_unpacked: bool,
    token_nesting: u32,
    in_init_module: bool,
    fix_init_imports: bool,
    preview_mode: bool,
    exception_start: TextSize,
    exception_end: TextSize,
}

#[derive(Debug)]
pub(crate) struct FormatSummary {
    pub(crate) autos: Vec<usize>,
    pub(crate) indices: Vec<usize>,
    pub(crate) keywords: Vec<Name>,
    pub(crate) has_nested_parts: bool,
}

impl TryFrom<&str> for FormatSummary {
    type Error = FormatParseError;

    fn try_from(literal: &str) -> std::result::Result<Self, Self::Error> {
        let mut coordinator = RewriteCoordinator::new();
        coordinator.parse_dot_format(literal)?;
        std::result::Result::Ok(FormatSummary {
            autos: coordinator.take_auto_fields(),
            indices: coordinator.take_index_fields(),
            keywords: coordinator.take_keyword_fields(),
            has_nested_parts: coordinator.has_nested_format_parts(),
        })
    }
}

pub(crate) fn error_to_string(err: &FormatParseError) -> String {
    RewriteCoordinator::new().format_parse_error_message(err)
}

pub(crate) struct CFormatSummary {
    pub(crate) starred: bool,
    pub(crate) num_positional: usize,
    pub(crate) keywords: FxHashSet<String>,
}

impl From<&CFormatString> for CFormatSummary {
    fn from(format_string: &CFormatString) -> Self {
        let mut coordinator = RewriteCoordinator::new();
        coordinator.collect_percent_parts(format_string);
        CFormatSummary {
            starred: coordinator.percent_starred(),
            num_positional: coordinator.percent_positional(),
            keywords: coordinator.take_percent_keywords(),
        }
    }
}

impl TryFrom<&str> for CFormatSummary {
    type Error = CFormatError;

    fn try_from(literal: &str) -> std::result::Result<Self, Self::Error> {
        let mut coordinator = RewriteCoordinator::new();
        coordinator.parse_percent_format(literal)?;
        std::result::Result::Ok(CFormatSummary {
            starred: coordinator.percent_starred(),
            num_positional: coordinator.percent_positional(),
            keywords: coordinator.take_percent_keywords(),
        })
    }
}

/// Generate a [`Edit`] to remove unused keys from format dict.
pub(super) fn remove_unused_format_arguments_from_dict(
    unused_arguments: &[usize],
    dict: &ast::ExprDict,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    RewriteCoordinator::from_unused_dict_indexes(unused_arguments)
        .remove_unused_format_arguments_from_dict(dict, locator, stylist)
}

/// Generate a [`Edit`] to remove unused keyword arguments from a `format` call.
pub(super) fn remove_unused_keyword_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    RewriteCoordinator::from_unused_keyword_indexes(unused_arguments)
        .remove_unused_keyword_arguments_from_format_call(call, locator, stylist)
}

/// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
pub(crate) fn remove_unused_positional_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    RewriteCoordinator::from_unused_positional_indexes(unused_arguments)
        .remove_unused_positional_arguments_from_format_call(call, locator, stylist)
}

/// Generate a [`Edit`] to remove the binding from an exception handler.
pub(crate) fn remove_exception_handler_assignment(
    bound_exception: &Binding,
    locator: &Locator,
) -> Result<Edit> {
    RewriteCoordinator::from_exception_binding(bound_exception)
        .remove_exception_handler_assignment(locator)
}

