fn coordinator_from_summary(summary: &FormatSummary) -> RewriteCoordinator {
    let mut coordinator = RewriteCoordinator::new();
    coordinator.set_format_analysis(
        summary.autos.clone(),
        summary.indices.clone(),
        summary.keywords.clone(),
        summary.has_nested_parts,
    );
    coordinator
}

