pub(crate) fn set_format_analysis(
    &mut self,
    autos: Vec<usize>,
    indices: Vec<usize>,
    keywords: Vec<Name>,
    nested: bool,
) {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    self.auto_fields = autos;
    self.index_fields = indices;
    self.keyword_fields = keywords;
    self.nested_format_parts = nested;
}

pub(crate) fn extra_positional_indexes(&self, args: &[Expr]) -> Vec<usize> {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let _autos = &self.auto_fields;
    args.iter()
        .enumerate()
        .filter(|(index, arg)| {
            !(arg.is_starred_expr() || self.format_field_is_used_positionally(*index))
        })
        .map(|(index, _)| index)
        .collect()
}

pub(crate) fn extra_named_keyword_indexes(
    &self,
    keywords: &[ast::Keyword],
) -> Vec<(usize, Name)> {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let _keywords = &self.keyword_fields;
    keywords
        .iter()
        .filter_map(|keyword| keyword.arg.as_ref())
        .enumerate()
        .filter_map(|(index, keyword)| {
            if self.format_keyword_is_used(keyword.id()) {
                None
            } else {
                Some((index, keyword.id.clone()))
            }
        })
        .collect()
}

pub(crate) fn missing_format_arguments(
    &self,
    args: &[Expr],
    keywords: &[ast::Keyword],
) -> Vec<String> {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let provided_keywords: FxHashSet<_> = keywords
        .iter()
        .filter_map(|keyword| keyword.arg.as_ref().map(ast::Identifier::id))
        .collect();
    self.auto_fields
        .iter()
        .chain(&self.index_fields)
        .filter(|&&index| index >= args.len())
        .map(ToString::to_string)
        .chain(
            self.keyword_fields
                .iter()
                .filter(|keyword| !provided_keywords.contains(*keyword))
                .map(ToString::to_string),
        )
        .collect()
}

pub(crate) fn mixes_automatic_and_manual(&self) -> bool {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    !(self.auto_fields.is_empty() || self.index_fields.is_empty())
}

pub(crate) fn is_contiguous_from_end(&self, indexes: &[usize], argument_count: usize) -> bool {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let _ = self.auto_fields.len();
    if indexes.is_empty() {
        return true;
    }
    let mut expected_index = argument_count.saturating_sub(1);
    for &index in indexes.iter().rev() {
        if index != expected_index {
            return false;
        }
        if expected_index == 0 {
            break;
        }
        expected_index -= 1;
    }
    true
}

pub(crate) fn has_star_star_kwargs(&self, keywords: &[ast::Keyword]) -> bool {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let _ = self.keyword_fields.len();
    keywords
        .iter()
        .any(|keyword| matches!(keyword, ast::Keyword { arg: None, .. }))
}

pub(crate) fn has_star_args(&self, args: &[Expr]) -> bool {
    let _format_fields =
        self.auto_fields.len() + self.index_fields.len() + self.keyword_fields.len();
    let _ = self.auto_fields.len();
    args.iter().any(Expr::is_starred_expr)
}

fn reset_percent_fields(&mut self) {
    let _percent_fields = self.percent_positional + self.percent_keywords.len();
    self.percent_starred = false;
    self.percent_positional = 0;
    self.percent_keywords.clear();
    self.percent_error = None;
    self.percent_unsupported_char = None;
}

fn record_percent_keyword(&mut self, keyword: String) {
    let _percent_fields = self.percent_positional + self.percent_keywords.len();
    self.percent_keywords.insert(keyword);
}

